import type { PracticeExam } from './lccaExams';

export const lccaGroExamsB: PracticeExam[] = [
  {
    id: 'exam-4',
    number: 4,
    title: 'Practice Exam 4',
    description: 'Advanced practice questions on Texas 26 TAC Chapter 748 (General Residential Operations), focusing on exceptions, multi-step rules, and comparisons between similar standards.',
    questions: [
      { id: 'e4q1', domain: 'Regulatory Framework', question: 'Which pairing of a change and the required written notice to your Licensing Representative is correct under §748.153?', options: ['Construction begins on a swimming pool or other permanent body of water: at least 30 days before construction begins', 'A change in operating hours: written notice at least 15 days before the change takes effect', 'A new individual becomes a controlling person: as soon as possible, but no later than two days after', 'A change of child-care administrator: written notice within 30 days after the change takes place'], correct: 2, explanation: 'Under §748.153(3)(B), a new controlling person requires written notice as soon as possible, but no later than two days after. Pool construction requires notice at least 15 days before construction begins (§748.153(2)(C)), operating-hours changes require at least 30 days\' notice (§748.153(1)(C)), and a change or vacancy in the administrator position requires notice within two days after (§748.153(3)(A)).' },
      { id: 'e4q2', domain: 'Regulatory Framework', question: 'A child is issued a ticket at school by law enforcement that does not result in the child being detained. What does §748.303(a)(7) require?', options: ['Notify Licensing and the parents, each within 24 hours of the date the operation becomes aware of the ticket', 'Notify law enforcement immediately and Licensing within 24 hours of becoming aware of the citation', 'Notify only the parents, as soon as possible but no later than 24 hours after you become aware', 'No report is required because the child was never detained or arrested at school'], correct: 2, explanation: 'Under §748.303(a)(7), a ticket or citation that does not result in the child being detained is reported to the parents as soon as possible, but no later than 24 hours after the GRO becomes aware of it. Licensing and law enforcement are not notified for this item. Compare §748.303(a)(6), where a child who is indicted, charged, or arrested must also be reported to Licensing within 24 hours.' },
      { id: 'e4q3', domain: 'Regulatory Framework', question: 'At 3:00 p.m. you determine that a 9-year-old is not on the premises and is still missing. Which reporting timeframe matches §748.303(a)(9)?', options: ['Law enforcement and parents within 2 hours of determining; Licensing within 2 hours of notifying law enforcement', 'Law enforcement immediately upon determining; Licensing and parents within 2 hours of notifying law enforcement', 'Law enforcement, Licensing, and parents all no later than 6 hours after the absence is discovered and he is still missing', 'Law enforcement within 2 hours of determining; Licensing and parents within 24 hours of the report'], correct: 0, explanation: 'For an unauthorized absence of a child developmentally or chronologically 6 to 12 years old, §748.303(a)(9) requires reports to law enforcement and to parents within 2 hours of determining the child is not on the premises (if still missing), and to Licensing within 2 hours of notifying law enforcement. The "immediately" timeframe with a 2-hour follow-up applies to children under 6 (§748.303(a)(8)), and the 6-hour timeframe applies to children 13 and older (§748.303(a)(10)).' },
      { id: 'e4q4', domain: 'Regulatory Framework', question: 'A child is treated at an urgent care clinic for a minor injury that is medically pertinent but is not a "substantial physical injury." What does §748.303(b) require?', options: ['A report to Licensing within 24 hours, because every clinic visit for an injury must be reported', 'No report to Licensing, but you must document it in the same manner as a serious incident', 'A notice to the parents only, within 24 hours, with no written documentation required', 'Nothing at all; only incidents that rise to a serious incident must be documented'], correct: 1, explanation: 'Under §748.303(b), a medically pertinent incident that does not rise to the level of a serious incident does not have to be reported, but the GRO must document it in the same manner as a serious incident, using the written report described in §748.311.' },
      { id: 'e4q5', domain: 'Administrator & Personnel', question: 'Under §748.533(b), an operation providing emergency care services must designate an employee solely responsible for administering those services. When is a designated employee other than the child-care administrator NOT required?', options: ['When the emergency care services program has a capacity of not more than 30 children', 'When the emergency care services program has a capacity of not more than 12 children', 'When fewer than 25 children in the operation receive treatment services', 'When the child-care administrator holds a full license rather than a provisional license'], correct: 0, explanation: '§748.533(b) requires an operation providing emergency care services to designate an employee in the staffing plan who is solely responsible for administering those services. A designated employee other than the child-care administrator is not required if the emergency care services program has a capacity of not more than 30 children.' },
      { id: 'e4q6', domain: 'Administrator & Personnel', question: 'An operation provides treatment services to 25 or more children with emotional disorders. Which set of qualifications must its professional level service provider meet under §748.563(a)?', options: ['A bachelor\'s degree in social work or a human services field, plus two years of documented full-time experience in a residential child-care operation or related field of child and family services', 'A master\'s degree in social work or a human services field with nine graduate hours on family and individual function, plus one year of full-time treatment experience', 'A nurse\'s degree or higher, plus one year of documented full-time experience in a medical or residential setting serving children with primary medical needs', 'A master\'s degree in any field from an accredited university, plus six months of documented full-time experience in a treatment setting serving children'], correct: 1, explanation: 'When treatment services for emotional disorders reach 25 or more children (or more than 30% of the children in care), §748.563(a) requires a master\'s degree or higher in social work or another human services field plus nine graduate credit hours focused on family and individual function and interaction, and one year of documented full-time experience in a treatment setting serving children. The nursing qualifications apply to primary medical needs (§748.563(b)), and the bachelor\'s option applies to other children (§748.563(c)).' },
      { id: 'e4q7', domain: 'Administrator & Personnel', question: 'You are screening a caregiver applicant who has previous work history providing care to children. Which approach satisfies the reference check requirements of §748.753(a) and (b) before hiring?', options: ['Contact at least two individuals, who may be relatives if they have known the applicant for six months or more, and document a summary of each call', 'Contact one professional reference who supervised the applicant in a child-care role; a second reference is optional if the first is thorough', 'Contact two unrelated individuals; an employer contact is required only if the applicant lists no personal references at all', 'Contact at least two unrelated individuals, one of them a current or former employer who supervised or knows the applicant\'s work in that role'], correct: 3, explanation: '§748.753(a) requires reference checks with at least two individuals unrelated to the applicant who can speak to suitability to work with or around children. Under §748.753(b), if the applicant has work history providing care or services to children, at least one reference must be a current or former employer who supervised or has knowledge of the applicant\'s history and job performance in that role.' },
      { id: 'e4q8', domain: 'Administrator & Personnel', question: 'A volunteer\'s family asks to take a child in care for a weekend visit. Which statement is correct under §748.725?', options: ['The volunteer and family must complete the same pre-service training and meet the same ratio qualifications that employees and caregivers must meet', 'The visit is treated as respite child-care, which only an operation offering emergency care services may provide, and it requires a placement agreement', 'It is a volunteer activity: the volunteer and family need the relevant background checks and you need the parent\'s written approval, but not caregiver qualifications', 'Verbal approval from the child\'s case manager is enough, and background checks are not required for a volunteer\'s family members'], correct: 2, explanation: 'Under §748.725, an overnight or weekend visit with a volunteer or the volunteer\'s family is a volunteer activity. Neither the volunteer nor the family must comply with employee or caregiver requirements, but they must meet the relevant background checks (§748.725(b)(1)) and you must get the parent\'s written approval (§748.725(b)(2)).' },
      { id: 'e4q9', domain: 'Training', question: 'Your policies allow emergency behavior intervention (EBI). A caregiver will care only for children receiving treatment services for emotional disorders. Under §748.863(a)(3), how much pre-service EBI training is required, and when?', options: ['16 hours, with at least half completed before the caregiver may be counted in ratio and all within 90 days of becoming a caregiver', '8 hours, with at least half completed before the caregiver may be counted in ratio and all within 90 days of becoming a caregiver', '16 hours, all of which must be completed before the caregiver is counted in the ratio for the first time on the cottage', '16 hours, with at least 4 hours before being counted in ratio and the remaining hours completed within 30 days of becoming a caregiver'], correct: 0, explanation: '§748.863(a)(3) requires 16 hours of EBI pre-service training for caregivers who care for children receiving treatment services for emotional disorders, intellectual disabilities, or autism spectrum disorder (8 hours for caregivers of child-care-only children). At least half the hours must be completed before the caregiver may be counted in ratio and the remaining hours within 90 days of becoming a caregiver. A caregiver may not administer any form of EBI, other than a short personal restraint, until all required hours are complete.' },
      { id: 'e4q10', domain: 'Training', question: 'Which of the following may NOT be counted toward a caregiver\'s annual training hours under §748.937?', options: ['Current first-aid and CPR certification training', 'Hours spent in the operation\'s orientation training', 'Half of the hours spent developing initial training curriculum relevant to the children served', 'Up to 15 hours of extra pre-service training beyond the required pre-service hours'], correct: 1, explanation: '§748.937(c) lists what may not be counted toward annual training: orientation training, required pre-service training, case staffings and supervisor conferences, and hours spent presenting training to others. By contrast, §748.937(b) allows first-aid and CPR, up to 15 carried-over extra pre-service hours, and half of the hours spent developing initial training curriculum.' },
      { id: 'e4q11', domain: 'Training', question: 'Under §748.931, how many annual training hours must a treatment director complete if the director does NOT hold a relevant professional license?', options: ['20 hours, compared with 15 hours for an employee of the same type who holds a relevant professional license', '15 hours, compared with 20 hours for an employee of the same type who holds a relevant professional license', '20 hours, the same as a licensed employee, because licensure hours are never credited', '50 hours, compared with 20 hours for an employee of the same type who holds a relevant professional license'], correct: 0, explanation: '§748.931(a) requires child-care administrators, professional level service providers, treatment directors, and case managers who do not hold a relevant professional license to complete 20 annual training hours, and those who do hold one to complete 15 hours. There are no annual EBI hours for these employees, but they must be retrained when there is a substantial change in EBI techniques, types, or policies (§748.931(e)).' },
      { id: 'e4q12', domain: 'Service Planning & Treatment', question: 'A child with an emotional disorder is being admitted directly from the child\'s family home. A psychological evaluation was completed 8 months before the admission date. Under §748.1219, is the evaluation acceptable?', options: ['Yes; an evaluation completed within 14 months of admission is acceptable for any child being admitted for treatment services, wherever the child lives', 'No; because the child is not coming from another regulated residential operation, it must have been completed within six months of admission', 'Yes, as long as the evaluation was signed and dated by a licensed psychologist who has experience with children', 'No; any evaluation more than 90 days old must be repeated by a licensed psychiatrist before the child is admitted'], correct: 1, explanation: 'Under §748.1219(1)(B), the psychiatric evaluation, psychological evaluation, or psychosocial assessment must have been completed within 14 months of admission if the child is coming from another regulated residential child-care operation, or within six months of admission if the child is not. An evaluation from 8 months earlier fails the six-month standard for a child coming from home.' },
      { id: 'e4q13', domain: 'Service Planning & Treatment', question: 'For a child receiving treatment services for an intellectual disability, how often must the child\'s intellectual functioning be re-evaluated under §748.1389?', options: ['At least every three years by a qualified psychologist, unless a psychologist sets a different, documented frequency for the child', 'At least every year by a licensed physician or psychiatrist, with the results reviewed by the service planning team at every service plan review', 'At least every 180 days during the first year of care, and then annually after the first year in care', 'Only when the service planning team or the child\'s parent requests a new evaluation of the child'], correct: 0, explanation: '§748.1389(a) requires re-evaluation of intellectual functioning at least every three years by a psychologist qualified to provide psychological testing. Under §748.1389(b), a psychologist may instead determine the need and frequency for a specific child, such as a young child, and the service planning team must document that determination and justification annually. The 180-day and annual timeframes describe service plan reviews (§748.1381), not intellectual re-evaluations.' },
      { id: 'e4q14', domain: 'Service Planning & Treatment', question: 'A child moves to a different cottage because of a bedroom renovation, not because of any change in the child\'s needs. What does §748.1383(b) require regarding the service plan review?', options: ['A full service plan review must be completed within 7 days of the move, with the parents invited to attend', 'Nothing is required, because moves within an operation never affect the timing of service plan reviews', 'A new preliminary service plan must be completed within 72 hours of the move to the new cottage and placed in the record', 'The service planning team must approve the decision not to review the plan, and you must document that decision'], correct: 3, explanation: 'Under §748.1383(a), you must review the service plan whenever a child\'s placement changes because of a change in the child\'s needs. If the placement changes for another reason, §748.1383(b) requires the service planning team to approve the decision not to review the plan and requires you to document that decision.' },
      { id: 'e4q15', domain: 'Service Planning & Treatment', question: 'A child receiving emergency care services is still in care on the 16th day. Which is required by that day under §§748.4211 and 748.4213?', options: ['A completed initial service plan and a signed placement agreement approved by the child\'s parent or the placing agency', 'A court order approving the extension of the child\'s stay, filed with the child\'s record and sent to Licensing', 'Documentation of the reason for continuing care and a written preliminary discharge plan that is reviewed at least weekly', 'A new admission assessment under §748.1217 completed and signed by a professional level service provider this week'], correct: 2, explanation: '§748.4211(a) requires documentation of the reason for continuing emergency care services in the child\'s record by the 16th day. For a child in emergency care for more than 15 days, §748.4213 requires a written preliminary discharge plan from the person responsible for the child, in the record on or before the 16th day, with written documentation that it is reviewed and updated at least weekly.' },
      { id: 'e4q16', domain: 'Child Rights & Discipline', question: 'A triggered review of emergency behavior intervention is required for a child who receives only child-care services (no treatment services). Who must participate under §748.2905?', options: ['Only the child\'s caregiver and the administrator, because no treatment services are involved and the review is informal', 'The treatment director alone, who may review the records and sign off without holding a team meeting or inviting the parents', 'The full service planning team, including the two additional professions in §748.1339(b), even though the child receives no treatment services', 'The service planning team, but the two additional professions are required only when the child receives treatment services'], correct: 2, explanation: '§748.2905(a) requires a full service planning team to participate in the triggered review and requires you to invite the child, as appropriate, and the parents. Under §748.2905(b), even if the child is not receiving treatment services, the two additional professions required by §748.1339(b) must be involved.' },
      { id: 'e4q17', domain: 'Child Rights & Discipline', question: 'Which statement about PRN orders for emergency behavior intervention is correct under §748.2507?', options: ['A psychologist who orders seclusion may use PRN orders if the psychologist reviews them at least every 30 days', 'PRN orders for mechanical restraint are allowed if a psychiatrist reviews them in writing every 30 days', 'PRN orders for emergency medication must be reviewed by a licensed psychiatrist at least every 90 days', 'A psychiatrist who orders seclusion may use PRN orders and must review them at least every 30 days'], correct: 3, explanation: 'Under §748.2507(a)(4), a licensed psychiatrist ordering seclusion may use PRN orders (a psychologist may not), and the psychiatrist must review them at least every 30 days with written clinical justification. PRN orders are not permitted for mechanical restraint (§748.2507(a)(5)), and PRN emergency medication orders must be reviewed by a licensed physician at least every 30 days (§748.2507(a)(3)).' },
      { id: 'e4q18', domain: 'Child Rights & Discipline', question: 'A child\'s mechanical restraint has reached its maximum length of time and the emergency continues. Which is correct under §§748.2805 and 748.2807?', options: ['A licensed psychiatrist, psychologist, or physician may issue the written order, up to a limit of four hours in total', 'Only a licensed psychiatrist may issue the continuation order, and it may not allow the restraint to exceed four hours', 'Only a licensed psychiatrist may issue the order, and there is no maximum limit while the emergency continues', 'The caregiver\'s supervisor may extend the restraint for up to two additional hours without any order'], correct: 1, explanation: 'Under §748.2805, a mechanical restraint may exceed the maximum time only if the caregiver obtains a written continuation order, before the time ends, from a licensed psychiatrist (for seclusion, a psychiatrist, psychologist, or physician may issue it) with written clinical justification that the emergency continues. §748.2807(d) provides that in no event may the order permit a seclusion or mechanical restraint to exceed four hours.' },
      { id: 'e4q19', domain: 'Child Rights & Discipline', question: 'Which operation may use seclusion as an emergency behavior intervention under §748.2451(a)(4)?', options: ['An operation where 5 of its 40 children receive treatment services for emotional disorders, if a psychiatrist has written an order', 'A therapeutic camp program serving children with emotional disorders, if the camp\'s policies permit seclusion', 'An operation providing emergency care services to a child, only while waiting for law enforcement or emergency medical services', 'Any operation whose policies allow seclusion and whose psychiatrist has written a PRN order for the child'], correct: 2, explanation: '§748.2451(a)(4) permits seclusion only (A) for a child with an emotional disorder or autism spectrum disorder in an operation serving treatment services to 25 or more such children or more than 30% of its children, and never for therapeutic camp children, or (B) for a child receiving emergency care services, and only while waiting for law enforcement or emergency medical services. Five of 40 children (12.5%) does not meet the threshold.' },
      { id: 'e4q20', domain: 'Health, Safety & Emergency', question: 'Which describes an outdoor swimming pool enclosure at your operation that meets §748.3603?', options: ['A six-foot fence that does not obscure the pool, with an outward-opening, self-closing, self-latching gate latched at least 60 inches high', 'A four-foot fence that surrounds the pool, with a gate that an adult latches whenever children are present in the water', 'A six-foot fence that uses a door or operable window of the living quarters as one section of the pool enclosure', 'A six-foot solid privacy fence, with a self-closing gate that staff may prop open during supervised swimming sessions'], correct: 0, explanation: '§748.3603 requires outdoor pools to be enclosed with a six-foot fence or wall constructed so it does not obscure the pool from view (d); doors, operable windows, or gates of living quarters may not be part of the enclosure (e); and gates must have self-closing, self-latching hardware at least 60 inches from the ground, be locked when the pool is not in use (f), open outward, and not be propped open (g).' },
      { id: 'e4q21', domain: 'Health, Safety & Emergency', question: 'Which requirement applies to the fire drills you must practice under §748.3239?', options: ['At least every three months, announced in advance so that children can prepare, with all children outside within three minutes of the alarm', 'At least every six months, using the main exit route, with children reaching the meeting place within five minutes', 'At least once a year, announced in advance, while severe weather drills are practiced every six months', 'At least every six months, unannounced, using alternate exit routes, with children reaching the meeting place within three minutes'], correct: 3, explanation: '§748.3239(a) requires an unannounced fire drill at least once every six months, in which you set off a fire alarm or smoke detector, participants use alternate exit routes, the children safely reach the designated meeting place within three minutes, and no one uses elevators. A severe weather drill is also required every six months (§748.3239(b)), and drills must be documented (§748.3239(d)).' },
      { id: 'e4q22', domain: 'Health, Safety & Emergency', question: 'A physician determines that an emergency under Family Code §266.009 requires a psychotropic medication for a child. What does §748.2257 require?', options: ['Follow the physician\'s orders without prior consent, then notify the parent and the person legally authorized to consent within 72 hours', 'Obtain written consent from the person legally authorized to consent before the first dose, even when the physician has declared an emergency', 'Follow the physician\'s orders, then notify Licensing and the parent within 24 hours after giving the medication', 'Follow the physician\'s orders, then obtain written consent from the legal consenter within 7 days of the first dose'], correct: 0, explanation: 'Under §748.2257(a), when a physician determines there is an emergency under Family Code §266.009 requiring a psychotropic medication, you follow the physician\'s orders and do not need consent beforehand. Within 72 hours after administering the medication you must notify the parent and the person legally authorized to give medical consent (§748.2257(b)), and the physician\'s emergency statement and prescription must be documented in the child\'s record (§748.2257(c)).' },
      { id: 'e4q23', domain: 'Health, Safety & Emergency', question: 'Which prescribed-medication error does NOT require you to contact a health-care professional immediately under §748.2203(a)?', options: ['A child received the wrong dosage', 'A scheduled dose was skipped or missed', 'A child received medication prescribed for another child', 'A child received expired medication'], correct: 1, explanation: '§748.2203(a) requires you to contact a health-care professional immediately for a prescribed-medication error, except for the types in §748.2201(4) and (5): a medication given at the wrong time and a dose that is skipped or missed. Wrong dosage, another child\'s medication, and expired medication all require immediate contact. All medication errors must still be documented within 24 hours (§748.2203(c)).' },
      { id: 'e4q24', domain: 'Daily Care & Program Operations', question: 'At dinner a child declines the entrée. In which situation must you offer an appropriate nutritional substitute under §748.1699?', options: ['The child dislikes the entrée and asks the caregiver for something that he would rather eat', 'The child chooses not to be present when the meal is scheduled', 'The child has refused the same meal twice during the week', 'The entrée conflicts with the child\'s food allergy or religious practice'], correct: 3, explanation: 'Under §748.1699(a), you must offer meals and snacks but may not force a child to eat, and you need not offer other food to a child who refuses a meal or chooses not to be present. If a meal is not appropriate for the child\'s individual needs, such as food allergies or religious reasons, you must offer an appropriate nutritional substitute (§748.1699(c)). Recurring eating problems must be discussed with the parent (§748.1699(b)).' },
      { id: 'e4q25', domain: 'Daily Care & Program Operations', question: 'Under §748.1021, which is required before a child in a transitional living program may be left without supervision?', options: ['The child is at least 14 years old and the administrator verbally approves the periods of unsupervised time each week', 'The child is at least 16 years old and has a signed agreement with the parent, with no written plan or team approval needed', 'The child has completed 90 days in the program and the treatment director signs a waiver of the supervision requirement', 'The child is at least 16, you have a written plan defining the periods of unsupervised time, and the service planning team approves the evaluation'], correct: 3, explanation: '§748.1021 allows a child in a transitional living program to be without supervision only if the child is 16 or older (a); you evaluate the child, including a written plan defining the periods the child may be unsupervised, a written plan for behavioral problems, and how the child can contact caregivers (b); the service planning team approves the evaluation (c); and you document the evaluation and approval and update it at service planning meetings (d).' },
    ],
  },
  {
    id: 'exam-5',
    number: 5,
    title: 'Practice Exam 5 — Final Prep',
    description: 'Final-prep practice at exam difficulty covering the Chapter 748 minimum standards for General Residential Operations across all seven domains.',
    questions: [
      { id: 'e5q1', domain: 'Regulatory Framework', question: 'A 16-year-old earns money at a part-time job. Under §748.161(b), when may you use the child\'s earnings to pay for the child\'s room and board?', options: ['Only if the use is part of the child\'s service plan and the child\'s parent approves it in writing', 'Whenever the child agrees in writing to contribute and a caregiver witnesses the signature', 'Whenever the administrator documents that the operation\'s costs exceed its available income that month', 'Only after the child has been in care for 90 days and the treatment director approves the arrangement'], correct: 0, explanation: '§748.161(b) prohibits using a child\'s personal earnings, allowances, or gifts to pay for room and board unless the use is part of the child\'s service plan and the parent approves it in writing. You must also account for a child\'s money separately from operation funds and give or send it to the child, parent, or next placement within 30 days of discharge.' },
      { id: 'e5q2', domain: 'Regulatory Framework', question: 'Which statement about required postings under §748.191 is correct?', options: ['The permit must be posted in every cottage home, even when it is also posted at the main office location', 'Emergency and evacuation relocation plans must be posted in each building and living quarters used by children', 'Postings may be kept in the administrator\'s office as long as they are available to anyone on request', 'Only the permit and the Keeping Children Safe notice must be posted; the evacuation plans may simply be kept on file'], correct: 1, explanation: '§748.191 requires posting, in a prominent and publicly accessible place, the permit, the Licensing notice Keeping Children Safe, and the emergency and evacuation relocation plans, with the evacuation plans posted in each building and living quarters used by children. An operation need not post its permit in cottage homes if the permit is posted at the main office location.' },
      { id: 'e5q3', domain: 'Regulatory Framework', question: 'You cannot renew your liability insurance because you cannot find an underwriter willing to issue a policy. What do §§748.159 and 748.160 require?', options: ['Notify Licensing within 24 hours of the lapse and keep operating; because the lapse was not the operation\'s choice, no notice to parents is required', 'Send Licensing written notice with the reason by the permit anniversary date, and notify each parent in writing within 14 days after coverage stops', 'Obtain a written waiver from Licensing before the coverage ends; if a waiver is granted, no further notice is needed', 'Notify only the parents, within 14 days; Licensing will learn of the lapse at the next scheduled inspection of the operation'], correct: 1, explanation: 'An inability to locate an underwriter is an acceptable reason not to carry insurance (§748.159(a)(2)), but you must send Licensing written notification, including the reason, by the anniversary date of the issuance of your permit (§748.159(b)). If you previously carried the insurance and stop, you must notify the parent of each child in care in writing within 14 days after you stop (§748.160(b)).' },
      { id: 'e5q4', domain: 'Regulatory Framework', question: 'Licensing cites your operation for a deficiency in the standard on abuse, neglect, or exploitation (§748.1101(b)(1)(B)). Which notification does §748.319 require?', options: ['Notify only the parents of the affected child within 24 hours using Form 2970, and keep a copy of the form', 'Notify the parents of each child residing at the operation within 30 days by any written means you prefer, and keep proof', 'Notify the parents of each child within five days using Form 2970, though no proof of the notice needs to be kept', 'Notify the parents of each child residing at the operation within five days using Form 7266, and keep proof of the notice'], correct: 3, explanation: '§748.319(a) requires you to notify the parents of each child residing at the operation, including children not in care on the day of the incident, within five days after you receive notification of the deficiency. For an abuse, neglect, or exploitation deficiency you must use Form 7266 (§748.319(c)), and you must keep proof of the notice available for Licensing (§748.319(d)). Form 2970 is for safe sleeping deficiencies.' },
      { id: 'e5q5', domain: 'Administrator & Personnel', question: 'Which statement about the person designated to handle emergencies under §748.537 is correct?', options: ['The person must be on call and accessible to caregivers but does not need to be a Licensed Child-Care Administrator', 'The person must hold a Licensed Child-Care Administrator license and be present at the operation whenever the administrator is away', 'The person must be physically present at the operation at all times, including nights, weekends, and holidays', 'Only Licensing, not the caregivers, must be told how to reach the person who is on call for emergencies'], correct: 0, explanation: '§748.537 requires a person designated to handle emergencies to be on call and accessible to caregivers (a), requires you to inform all caregivers and Licensing of the system and how to contact the person (b), and states the employee is not required to be a Licensed Child-Care Administrator (c).' },
      { id: 'e5q6', domain: 'Administrator & Personnel', question: 'When must a general residential operation have a full-time treatment director under §748.601?', options: ['When it provides treatment services to 25 or more children, or to more than 30% of the children in its care', 'When it provides treatment services to any child, regardless of how many children in care receive those services', 'When it provides treatment services to 10 or more children, regardless of the share of children in its care', 'Only when it operates as a residential treatment center that serves children with emotional disorders'], correct: 0, explanation: '§748.601 requires a treatment director if you provide treatment services to 25 or more children, or to more than 30% of the children in your care. The treatment director must be a full-time employee of the operation.' },
      { id: 'e5q7', domain: 'Administrator & Personnel', question: 'A 16-year-old will attend a friend\'s party as an approved unsupervised childhood activity. Which is NOT required of the caregiver under §748.685(d)?', options: ['Knowing where the child will be', 'Giving the child a specific time to return', 'Providing, arranging, or confirming transportation to and from the activity', 'Arranging for an employee to stay at the party and observe the child'], correct: 3, explanation: 'For an unsupervised childhood activity, §748.685(d) requires the caregiver to know where the child will be, give a specific return time, provide, arrange, or confirm transportation, give the child a way to contact the caregiver in an emergency, and be available to respond if the child needs immediate help. It does not require an employee to stay and observe, which would make the activity supervised.' },
      { id: 'e5q8', domain: 'Administrator & Personnel', question: 'A volunteer keeps a handgun locked in the glove box of her personal car, parked on the operation\'s grounds. What does §748.511 say?', options: ['It is allowed because the handgun is locked and inaccessible to children while the car is parked on the grounds', 'It is allowed if the administrator gives the volunteer written permission to keep the handgun locked in her car', 'It is allowed if the volunteer holds a concealed-carry license and keeps the handgun out of sight at all times', 'Not allowed; a volunteer may not possess a handgun at the operation, even in a car parked on the grounds'], correct: 3, explanation: '§748.511 states that an employee, contract service provider, or volunteer may not be in possession of a handgun while at your operation or while caring for children. The technical assistance explains the intent includes handguns on the grounds, including in vehicles parked on the property or used to transport children. This standard is weighted High.' },
      { id: 'e5q9', domain: 'Training', question: 'Your operation serves children ages 8 through 17. Which CPR certification satisfies §748.911(b)?', options: ['At least one caregiver counted in ratio holds both pediatric and adult CPR, or two caregivers in ratio together hold each type', 'Only pediatric CPR is needed, because many of the children served are younger than 12 years old', 'Adult CPR for every caregiver, with pediatric CPR optional because the oldest children are 17 years old', 'Pediatric and adult CPR held by the administrator or another employee, who does not need to be counted in the child-to-caregiver ratio'], correct: 0, explanation: 'Under §748.911(b)(3), when an operation serves children from birth through 17, at least one caregiver counted in the child-to-caregiver ratio must hold both pediatric and adult CPR, or one caregiver may hold pediatric CPR and another counted caregiver adult CPR. Pediatric alone applies only if all children are under 12, and adult alone only if all are 12 or older.' },
      { id: 'e5q10', domain: 'Training', question: 'Which CPR training meets the requirements of §748.913?', options: ['A fully online video course that ends with a multiple-choice quiz and a printable certificate of completion for the personnel file', 'A two-hour classroom lecture on CPR theory taught by the administrator, followed by a short written test', 'Any course that issues a certificate, whether or not it includes hands-on practice with a manikin', 'Training that follows American Heart Association layperson guidelines and includes manikin practice with written and hands-on testing'], correct: 3, explanation: '§748.913 requires CPR training to follow the American Heart Association guidelines for a layperson and consist of a curriculum that includes use of a CPR manikin and both written and hands-on skill-based instruction, practice, and testing. Blended learning with online components is allowed if it meets those criteria.' },
      { id: 'e5q11', domain: 'Training', question: 'A newly hired employee completes 4 hours of orientation covering the operation\'s philosophy and policies. Can those hours count toward pre-service training under §748.865?', options: ['Yes, up to 4 hours may be credited toward the 8 hours of general pre-service training', 'Yes, but only for caregivers, not for other employees', 'No; orientation must be separate from the pre-service training requirement', 'Yes, if the orientation is documented in the personnel record'], correct: 2, explanation: '§748.865 states that time spent in orientation cannot count toward pre-service training. The technical assistance explains that orientation covers the organization and how it operates, while pre-service training prepares employees to do their jobs competently, so orientation also may not count toward annual training (§748.937(c)(1)).' },
      { id: 'e5q12', domain: 'Training', question: 'A person who worked as a caregiver at another general residential operation seven months ago is hired as a caregiver at your operation. Which statement is correct?', options: ['The person is exempt from both general pre-service training and orientation, because of the recent employment history', 'The person must repeat all 8 hours of general pre-service training before being counted in the ratio', 'The person is exempt from general pre-service training only if the previous employment was at your own operation within the last 12 months', 'The person is exempt from the 8 hours of general pre-service training but still needs orientation at your operation before contacting children'], correct: 3, explanation: '§748.867(a) exempts a caregiver from the 8 hours of general pre-service training if the caregiver was employed as a caregiver in a general residential operation during the past 12 months, at any such operation. The orientation exemption in §748.833 applies only to a person who was a caregiver or employee at your operation during the past 12 months, so this caregiver still needs orientation before contact with children (§748.831).' },
      { id: 'e5q13', domain: 'Service Planning & Treatment', question: 'Under §748.1205(b), when must you document a child\'s full admission information for a child admitted for emergency care services?', options: ['Before the child is admitted, at the intake interview, so that nothing is missing from the record on the first day', 'Within 7 days after admission, once the child\'s medical examination has been completed', 'Within 40 days after admission, together with the completed admission assessment', 'Within 72 hours after admission, documenting reasonable efforts for any information that is unavailable'], correct: 3, explanation: 'For a child admitted for emergency care services, §748.1205(b) requires documenting the reason for admission upon admission and the information in §748.1205(a) within 72 hours after admission. If any information is not available in that time, you must document the reasonable efforts made to obtain it.' },
      { id: 'e5q14', domain: 'Service Planning & Treatment', question: 'Under §748.1207(c), who may sign a placement agreement on the child\'s own behalf without the consent of the child\'s parent?', options: ['A child in a transitional living program who is 16 or older, unmarried, and pregnant', 'A 15-year-old in a transitional living program who manages the child\'s own finances', 'A 17-year-old receiving treatment services for an emotional disorder', 'A child of any age who has been in the program for more than 90 days and has completed life-skills training'], correct: 0, explanation: '§748.1207(c) allows, for a transitional living program, a child 16 years of age or older to sign the placement agreement without parental consent if the child resides separate and apart from the parent and manages the child\'s own financial affairs, is unmarried and pregnant, or is unmarried and a parent.' },
      { id: 'e5q15', domain: 'Service Planning & Treatment', question: 'A copy or summary of the initial service plan must, at a minimum, be given to a child who is at least:', options: ['10 years old, with no exceptions, whether or not the child is able to understand the plan', '12 years old, unless the child\'s parent objects to the child receiving a copy', '14 years old, unless you document justification for not providing it', '16 years old, unless the treatment director objects to the child receiving the plan'], correct: 2, explanation: 'Under §748.1349(a)(1), you must at a minimum give a copy or summary of the initial service plan to a child 14 years of age or older unless there is justification for not providing it. If you do not provide it, you must document the justification in the record (§748.1349(c)). If you do, the child must review and sign it, or you must document the refusal (§748.1349(b)).' },
      { id: 'e5q16', domain: 'Service Planning & Treatment', question: 'Which of the following is an emergency discharge or transfer under §748.1443?', options: ['A child is absent from the operation and cannot be located', 'A child completes the program and returns to the family as planned', 'A child is moved between two of your programs after a regular service plan review', 'A parent gives written notice a month before withdrawing the child'], correct: 0, explanation: '§748.1443 lists four emergency discharge or transfer situations: the parent withdraws the child unexpectedly, a medical emergency requires inpatient care, the child is absent and cannot be located, or there is an immediate danger to the child or others and you determine you cannot serve the child. Planned, noticed moves are not emergencies.' },
      { id: 'e5q17', domain: 'Child Rights & Discipline', question: 'Within how many days after admission must you review a child\'s rights with the child and the child\'s parent and give each a written copy?', options: ['Three days', 'Fourteen days', 'Seven days', 'Thirty days'], correct: 2, explanation: '§748.1103(a) requires you, within seven days after admission, to review the child\'s rights with the child and the child\'s parent (unless the parent\'s consent is not required) and to give both a written copy. The rights must be written in simple, non-technical terms and the person informed must sign a statement that the rights were read and understood (§748.1103(b), (d)).' },
      { id: 'e5q18', domain: 'Child Rights & Discipline', question: 'A search of a child involves removing clothing other than outer clothing. Which is required by §748.1113(d) through (f)?', options: ['Any caregiver may conduct it if the administrator approves it and the child\'s parent is notified afterward', 'A caregiver of the child\'s gender conducts it, a second caregiver witnesses it, and other children do not witness it', 'A same-gender caregiver conducts it alone, without a witness, to protect the child\'s privacy and dignity', 'A licensed nurse must conduct it, with the child\'s caseworker present, and the other children must be moved to another room'], correct: 1, explanation: 'Under §748.1113(d), only a caregiver of the same gender as the child may conduct a search involving removal of clothing other than outer clothing (coats, jackets, hats, gloves, shoes, socks). A second caregiver must witness it (§748.1113(e)), and the caregiver must ensure other children do not witness it (§748.1113(f)).' },
      { id: 'e5q19', domain: 'Child Rights & Discipline', question: 'A child spray-paints a wall at the operation. Which consequence is permitted under §748.2305(b)?', options: ['Requiring the child to dig a hole and then refill it', 'Requiring the child to repaint the wall as a logical consequence', 'Requiring the child to run laps until tired', 'Requiring the child to hold a kneeling position for 20 minutes as a quiet reflection'], correct: 1, explanation: '§748.2305(b) explains that unproductive work does not include work that corrects damage the child\'s behavior caused, such as repainting a defaced fence or wall, which is an acceptable logical consequence. Digging and refilling a hole is unproductive work, and forced exercise or holding a physical position is corporal punishment (§748.2303(b)).' },
      { id: 'e5q20', domain: 'Health, Safety & Emergency', question: 'Who may destroy accumulated discontinued or expired medication under §748.2103(b)?', options: ['A health-care professional or pharmacist, or the licensed child-care administrator together with another adult who is not a resident', 'Any two caregivers on shift together, as long as they log the date, the child\'s name, and the medication destroyed, and both sign', 'The licensed child-care administrator alone, as long as the date and medication destroyed are logged', 'A caregiver and the child to whom the medication was prescribed, so that the child can observe it'], correct: 0, explanation: '§748.2103(b) requires destruction in accordance with state and federal law, in a way that ensures children cannot access the medication, by a health-care professional or pharmacist, or by the licensed child-care administrator and another adult who is not a resident. Until then, the medication must be inventoried and stored separately from current medications (§748.2103(a)).' },
      { id: 'e5q21', domain: 'Health, Safety & Emergency', question: 'Which lists the correct maximum interval for each required inspection under Subchapter O?', options: ['Sanitation every 24 months, gas leak every 12 months, fire every 12 months', 'Sanitation every 12 months, gas leak every 24 months, fire every 12 months', 'Sanitation every 12 months, gas leak every 12 months, fire every 24 months', 'Sanitation every 24 months, gas leak every 24 months, fire every six months'], correct: 1, explanation: 'A sanitation inspection is required at least once every 12 months (§748.3001(a)(2)), a gas leak inspection at least once every 24 months (§748.3061(2)), and a fire inspection at least once every 12 months (§748.3101(2)). Each is also required before your initial permit is issued.' },
      { id: 'e5q22', domain: 'Health, Safety & Emergency', question: 'Which item must each first-aid kit contain under §748.3273?', options: ['A children\'s pain reliever such as ibuprofen or acetaminophen', 'An epinephrine auto-injector', 'A current guide to first aid and emergency care', 'A splint set'], correct: 2, explanation: '§748.3273 lists the minimum supplies: a current guide to first aid and emergency care, adhesive tape, antiseptic solution or wipes, adhesive bandages, scissors, sterile gauze pads, a thermometer, tweezers, and waterproof disposable gloves. Under §748.3271, all separate living areas and buildings, and all field trips, must have a complete kit.' },
      { id: 'e5q23', domain: 'Health, Safety & Emergency', question: 'Under §748.4043(a), which is a condition for transporting children in the bed of a pick-up truck on the facility grounds?', options: ['Children must be at least 10 years old and may sit on the tire wells', 'Children must be at least 13 years old and may sit on the tailgate if the driver goes slowly', 'Children must be at least 13 years old, seated, and not leaning against the tailgate', 'Children may ride on public roads if the speed stays below 30 miles per hour'], correct: 2, explanation: '§748.4043(a) allows children to ride in a pick-up bed on facility grounds only if they are at least 13, seated, not sitting on the side, tire wells, or tailgate, not leaning against the tailgate, the tailgate is securely closed, and the vehicle travels at a safe speed with a knowledgeable driver. Open-bed pick-up trucks or trailers must not be used to transport children on public roads (§748.4043(a)(8)).' },
      { id: 'e5q24', domain: 'Daily Care & Program Operations', question: 'To serve a child a therapeutic or special diet, §748.1701(a) requires written approval in the child\'s record from:', options: ['The child\'s primary caregiver, the cook, or the administrator on duty', 'A licensed physician or a registered or licensed dietitian', 'A professional level service provider', 'The child\'s school nurse'], correct: 1, explanation: '§748.1701(a) requires written approval from a licensed physician or a registered or licensed dietitian to serve a therapeutic or special diet. You must then give diet information to all employees who prepare and serve food and to the child\'s caregivers (§748.1701(b)).' },
      { id: 'e5q25', domain: 'Daily Care & Program Operations', question: 'For school-age children, what does §748.1691(b) require about meals?', options: ['Three meals daily and a snack only on weekends, with no more than 12 hours between the last meal and the first meal of the next day', 'Two meals and two snacks daily, with no more than 14 hours between the last snack and the next day\'s first meal', 'Three meals and at least one snack daily, with no more than 14 hours between the last meal or snack and the next day\'s first meal', 'Three meals and one snack daily, with no more than 18 hours between the last snack and the next day\'s first meal'], correct: 2, explanation: 'Under §748.1691(b), a school-age child must be given three meals and at least one snack a day, and no more than 14 hours may pass between the last meal or snack of the day and the first meal of the following day.' },
    ],
  },
  {
    id: 'exam-8',
    number: 8,
    title: 'Practice Exam 8 — Scenario Exam',
    description: 'Fifty scenario-based questions in which you act as the GRO administrator applying Chapter 748 minimum standards to realistic situations.',
    questions: [
      { id: 'e8q1', domain: 'Regulatory Framework', question: 'You are the GRO administrator. A burst pipe floods the boys\' cottage overnight, and the building cannot be used safely or sanitarily by the children. What is the best course of action?', options: ['Complete the repairs first, since the flood was an internal maintenance issue, and report it to Licensing at the next scheduled inspection', 'Report to law enforcement within 1 hour and to Licensing within 2 hours, because the building is unsafe for the children', 'Move the children to safety, then report to Licensing and notify parents as soon as possible, no later than 24 hours after the incident', 'Notify Licensing within 24 hours, but notify parents only if a child was injured or lost personal belongings'], correct: 2, explanation: 'Under §748.303(e)(1), an incident that renders all or part of the GRO unsafe or unsanitary for a child, such as a fire or flood, must be reported to Licensing and to parents as soon as possible, but no later than 24 hours after the incident. It must also be documented in a written report under §748.311.' },
      { id: 'e8q2', domain: 'Regulatory Framework', question: 'You are the GRO administrator. An employee tells you a night caregiver admitted using marijuana at a party last Saturday, and today is Tuesday. What must you do?', options: ['Report it to Licensing and to every parent within 2 hours of learning of it, because drug allegations are always treated as urgent', 'Report it only to law enforcement, because drug use is a crime and Licensing is notified by the police', 'Report the allegation to Licensing within 24 hours after learning of it; notifying parents is not required for this incident type', 'Wait for the caregiver\'s drug test result, then report to Licensing within 24 hours of receiving the result'], correct: 2, explanation: '§748.303(e)(5) requires a report to Licensing within 24 hours after learning of an allegation that a person under the auspices of the GRO who directly cares for or has access to a child abused drugs within the past seven days. The table does not require parent notification for this item.' },
      { id: 'e8q3', domain: 'Regulatory Framework', question: 'You are the GRO administrator. Deputies arrive with a search warrant and execute it at one of your buildings. After cooperating, what are your reporting obligations under §748.303(e)(8)?', options: ['Report it to Licensing as soon as you become aware of it; parents need not be notified for this item', 'Report it to Licensing and notify every parent within 24 hours, because a search affects all children in care', 'No report is needed unless a child is named in the warrant or a child was present when it was executed', 'Notify the parents only, within 2 hours, because Licensing learns of search warrants from law enforcement'], correct: 0, explanation: 'When a search warrant is executed by law enforcement at the GRO, §748.303(e)(8) requires a report to Licensing as soon as the GRO becomes aware of the situation. Parents are not required to be notified for this item.' },
      { id: 'e8q4', domain: 'Regulatory Framework', question: 'You are the GRO administrator and hold a provisional child-care administrator\'s license. A second residential operation asks you to also serve as its administrator. What is the best response?', options: ['Accept, as long as both operations are in good standing and you split a full-time schedule between them', 'Decline, because a provisional license holder may serve as administrator at only one residential operation', 'Accept, if the two operations are on the same campus and you notify Licensing within two days', 'Accept, if both operations have a written professional staffing plan that names a back-up administrator'], correct: 1, explanation: 'Under §748.533(c), a child-care administrator with a provisional child-care administrator\'s license may serve as a licensed administrator at only one residential child-care operation. The two-operation arrangement in §748.533(a) is not available until you hold a full license.' },
      { id: 'e8q5', domain: 'Regulatory Framework', question: 'You are the GRO administrator moving child records to an electronic system. Which element must your policies and procedures add under §748.345?', options: ['Annual independent penetration testing of the system', 'Storage of all data on servers located in Texas', 'Requirements for routine back-up of the data', 'Encryption of every file with a vendor approved by Licensing'], correct: 2, explanation: 'If you keep electronic records, §748.345 requires policies that address what records go in the external paper file versus the electronic file, computer security (confidentiality, passwords, employee procedures), routine back-up of data, anti-virus protection, and limiting access to authorized persons. The other options are not listed requirements.' },
      { id: 'e8q6', domain: 'Regulatory Framework', question: 'You are the GRO administrator. Licensing asks to review the personnel record of an employee who resigned eight months ago. The archived record is stored at your corporate office across town. Is this arrangement compliant?', options: ['No; archived personnel records may never leave the operation where the employee worked, and must be kept in a locked cabinet there', 'Yes, if the record can be produced within 7 days of the request and the employee\'s name is on a master list', 'Yes, because personnel records may be discarded six months after the employee\'s last day of employment', 'Yes, if the record is available for Licensing\'s review within 48 hours and appears on the master list kept in the main office'], correct: 3, explanation: '§748.361(b) allows archived personnel records to be kept at the operation and/or a designated location as long as they are available for review within 48 hours, and §748.361(e) requires a master list in the main office noting the location of active and archived records. Personnel records must be kept a year after the last day of employment (§748.431(b)).' },
      { id: 'e8q7', domain: 'Regulatory Framework', question: 'You are the GRO administrator. During an inspection, the inspector finds a child\'s peanut allergy documented only deep inside the medication section of the file. What does §748.393(b)(2) require?', options: ['Record known allergies and chronic conditions on the exterior of the record or another clearly visible spot, noting "no known allergies" when applicable', 'Allergies may be recorded anywhere in the file, such as the medication section, as long as the whole file is kept locked', 'Allergies must be recorded only in the child\'s service plan, which the caregivers review at each service plan meeting', 'Only life-threatening allergies must be recorded, and they belong on the placement agreement or the medical consent form rather than on the exterior of the file'], correct: 0, explanation: '§748.393(b)(2) requires documentation of known allergies and chronic health conditions on the exterior of the child\'s record or in another place clearly visible to persons with access to the record, including a notation of "no known allergies" when applicable. This is a Medium-High weighted standard.' },
      { id: 'e8q8', domain: 'Regulatory Framework', question: 'You are the GRO administrator. An inspector arrives unannounced during operating hours and asks to review and copy active child records. Your assistant says the records can be sent tomorrow. What is the best response?', options: ['Allow the inspector to review the records but not to copy them, because child records are confidential and may be released only with consent', 'Make the active records available immediately for review and copying, and allow reasonable access to your storage and file areas', 'Provide the records within 48 hours, as for records that are archived, so that the files can be organized first', 'Ask the inspector to schedule an appointment so the records can be organized and a staff member can sit in'], correct: 1, explanation: '§748.399(a) requires active records to be available for Licensing\'s immediate review and reproduction, and §748.399(b) requires reasonable access to storage and file areas. §748.151(4) also requires you to allow inspection during hours of operation, and §748.397 permits release of records to Licensing without consent.' },
      { id: 'e8q9', domain: 'Administrator & Personnel', question: 'You are the GRO administrator. During waking hours, one cottage group has five children ages 7 to 12 and one 4-year-old, and one of the children receives treatment services. How many caregivers must you schedule?', options: ['One caregiver, because six children fall under the 1:8 limit', 'Two caregivers', 'Three caregivers', 'One caregiver plus an on-call employee'], correct: 1, explanation: 'Under §748.1003(a), a single caregiver may care for five children during waking hours if at least one child in the group requires treatment services, and children younger than five count as two. This group counts as 5 + 2 = 7 children, which exceeds 5, so two caregivers are required. The 1:8 ratio applies only when no child in the group requires treatment services.' },
      { id: 'e8q10', domain: 'Administrator & Personnel', question: 'You are the GRO administrator. A 17-year-old on probation has been ordered to complete 40 hours of community service and asks to do them at your campus. What do you do?', options: ['Accept, if the teen completes a background check and signs the abuse-reporting statement', 'Accept, if a caregiver supervises the teen at all times', 'Accept, if the teen\'s parent consents in writing', 'Decline, because a person may not perform community service hours at your operation'], correct: 3, explanation: '§748.731 states a person may not perform community service hours at your operation, including service required because the person is on probation or parole or is otherwise court-ordered to perform service because of criminal activity. It is weighted Medium-High.' },
      { id: 'e8q11', domain: 'Administrator & Personnel', question: 'You are the GRO administrator hiring a caregiver. The applicant\'s previous employer has not answered two phone calls and an email. What must your personnel file show under §748.751 if you hire the applicant?', options: ['A signed and notarized statement from the applicant that the previous employment history is accurate, kept with the application papers', 'Two or more attempts to contact the previous employer, with the reason documented if the employer is determined permanently unreachable', 'One attempt to contact the previous employer and a note that no response was received after a reasonable wait', 'A reference from the applicant\'s family member in place of the previous employer\'s verification of the dates of work'], correct: 1, explanation: '§748.751(a) requires employment verification, to the extent possible, by contacting the previous employers listed before hiring. Under §748.751(b), if the applicant is hired you must document the employment history and two or more attempts to contact a previous employer, and, if the employer is permanently unreachable, the reason for that determination.' },
      { id: 'e8q12', domain: 'Administrator & Personnel', question: 'You are the GRO administrator. A caregiver arrives for the evening shift appearing impaired, and a coworker says it has happened before. What is the best course of action?', options: ['Allow the shift to continue if the caregiver is not counted in the child-to-caregiver ratio and a second caregiver stays with the group', 'Document the concern in the personnel record and address it at the caregiver\'s next scheduled performance review', 'Assign the caregiver to supervise only the oldest children until the concern can be reviewed the next business day', 'Keep the caregiver away from the children; a person known to present a danger by behavior or health status may not be at the operation'], correct: 3, explanation: '§748.505(a) provides that an employee\'s behavior or health status must not present a danger to children, and §748.535(3)(H) makes the administrator responsible for ensuring that persons whose behavior or health status is known to present a danger to children are not allowed at the operation.' },
      { id: 'e8q13', domain: 'Administrator & Personnel', question: 'You are the administrator of two contiguous general residential operations. How must your schedule be structured under §748.531(b)?', options: ['You must work a full-time schedule at each operation, because each permit requires a full-time administrator who is on site daily', 'You may work part-time at each operation as long as a designee holding a license is on call whenever you are away', 'You must split a full-time schedule between the two operations as described in each operation\'s professional staffing plan', 'You must work full-time at the larger operation and be reachable by telephone during business hours at the other one'], correct: 2, explanation: 'An administrator may serve two residential child-care operations if the conditions of §748.533 are met (both in good standing, manageable size and scope, and contiguous GROs). Under §748.531(b), the administrator must split a full-time schedule between the two operations as described in the professional staffing plans for each operation.' },
      { id: 'e8q14', domain: 'Administrator & Personnel', question: 'You are the GRO administrator opening a program that will serve 27 children with primary medical needs. Which staffing arrangement satisfies §748.569?', options: ['A licensed registered nurse on staff or contract who works full-time, with 24-hour availability of nursing, medical, and psychiatric services', 'A licensed vocational nurse who works full-time with no registered nurse on staff, plus a physician on call at all hours for emergencies', 'A registered nurse who visits the operation weekly, with trained caregivers handling the daily medical needs and calling the nurse when problems arise', 'A nurse aide on every shift, supervised by a physician who reviews the children\'s records at least monthly'], correct: 0, explanation: 'When treatment services for primary medical needs reach 25 or more children (or more than 30% of the children in care), §748.569 requires a licensed registered nurse on staff or contract who works full-time (relieved on days off by an RN or a supervised LVN), and arrangements for 24-hour availability of nursing, medical, and psychiatric services, licensed nursing with 24-hour direction or supervision, and other listed supports.' },
      { id: 'e8q15', domain: 'Administrator & Personnel', question: 'You are the GRO administrator. A registered nurse wants unlicensed caregivers to perform a nursing task for a child with primary medical needs. What must be true under §748.575?', options: ['The administrator approves the delegation after the caregivers complete first-aid and CPR training, sign a competency form, and pass a written test', 'The caregivers observe the nurse perform the task once and then sign a statement that they are competent to perform it', 'The treatment director decides which nursing tasks are delegated, because the director is responsible for the treatment program', 'The delegation criteria are met, you follow a training protocol developed with physician or nurse input, and a physician or RN instructs the caregivers'], correct: 3, explanation: '§748.575 allows a physician or registered nurse to delegate nursing tasks to unlicensed caregivers only if all criteria are met: the task is within sound nursing judgment to delegate and can be done safely, the operation develops and follows a training protocol with physician or RN input addressing identification, instruction, competency demonstration, and re-evaluation, the final decision rests with the physician or RN, and a physician or RN instructs the caregivers.' },
      { id: 'e8q16', domain: 'Training', question: 'You are the GRO administrator. Your operation allows emergency behavior intervention, and a caregiver in her second week has not finished the required EBI training. A child becomes physically aggressive. What may she do?', options: ['Use any personal restraint, as long as another fully trained caregiver is present and monitors the child\'s breathing and positioning', 'Use no physical intervention of any kind until her training is complete, even to protect a child from injury', 'Use only a short personal restraint; she may not administer any other form of EBI until all required EBI training hours are complete', 'Use any form of EBI once she has completed half of the required hours, as long as a supervisor approves'], correct: 2, explanation: 'Under §748.863(a)(3)(C)(ii), a caregiver may not administer any form of EBI before completing all the required EBI training hours, except for administering a short personal restraint. §748.2453 likewise allows only a caregiver qualified in EBI to administer any form of EBI other than a short personal restraint.' },
      { id: 'e8q17', domain: 'Training', question: 'You are the GRO administrator. A caregiver hired five weeks ago has not yet been certified in first aid and is scheduled as the only caregiver counted in ratio on the night shift. What does §748.911(c) require?', options: ['She must be certified in both first aid and CPR before working any shift as the only caregiver counted in the child-to-caregiver ratio', 'She must already be CPR certified and able to respond to emergencies; first-aid certification is due within 90 days of employment', 'She may be the only caregiver as long as she completes CPR certification within 90 days of her date of hire', 'Neither certification is required until her first annual training, which is due within 12 months of hire'], correct: 1, explanation: '§748.911(c) requires each caregiver to be certified in first aid within 90 days of employment and to be certified in CPR and able to respond to emergencies prior to being the only caregiver counted in the child-to-caregiver ratio. At five weeks she is inside the first-aid window but must already hold CPR certification to work alone.' },
      { id: 'e8q18', domain: 'Training', question: 'You are the GRO administrator. Your operation tracks annual training by each employee\'s hire anniversary, but you prorate new hires to the calendar year because it is easier. Is this acceptable under §748.935?', options: ['Yes; you may choose the method separately for each employee, as long as each person\'s dates are documented', 'No; whichever method you choose, you must use it consistently throughout the operation', 'Yes, as long as new hires finish their hours within 90 days of hire', 'No; prorating to the calendar year is never allowed, so every employee must use the anniversary method'], correct: 1, explanation: '§748.935(a) sets annual training within 12 months of hire and each subsequent 12-month period, and §748.935(b) allows prorating from the date of hire to the end of the calendar or fiscal year instead. Under §748.935(c), whichever method you use, you must use it consistently throughout your operation.' },
      { id: 'e8q19', domain: 'Training', question: 'You are the GRO administrator. A caregiver at an operation with fewer than 25 children receiving treatment services, and fewer than 30% of its population, completes 38 annual training hours this year. How many hours may be carried over to next year?', options: ['A maximum of 15 hours', 'All 18 extra hours', 'None, because carry-over is not allowed', 'A maximum of 20 hours'], correct: 0, explanation: 'This caregiver must complete 20 annual hours (§748.930(a)(1)). §748.937(e) allows a person who earns more than the minimum to carry over a maximum of 15 annual training hours to the next year, so only 15 of the 18 extra hours carry over.' },
      { id: 'e8q20', domain: 'Training', question: 'You are the GRO administrator at an operation that allows EBI. A caregiver completed his EBI training through a self-paced online course ending with a quiz. What is the problem under §748.941?', options: ['EBI training may be self-instructional if it totals no more than three hours, the course is approved, and the caregiver passes a final quiz', 'Nothing is wrong; an online quiz demonstrates competency for any type of training the operation requires, so long as the quiz is documented', 'EBI training must be instructor-led and competency-based, with participants showing knowledge in writing and the physical techniques they may use', 'EBI training must be taught by a physician or registered nurse, who must also certify each caregiver\'s competency in writing every year'], correct: 2, explanation: '§748.941(b) requires EBI training to be instructor-led, and §748.941(c) requires the instructor to be certified in a recognized EBI method or otherwise able to document knowledge, the training to be competency-based, and each participant to demonstrate knowledge in writing and, if the GRO allows EBI, to demonstrate the physical techniques the participant may use.' },
      { id: 'e8q21', domain: 'Training', question: 'You are the GRO administrator. A newly hired cook has no direct-care duties. What suicide prevention training must she receive under §748.125(c)(1)?', options: ['None, because only caregivers who directly supervise children are required to complete any suicide prevention training', 'At least one hour of suicide prevention training annually, because all caregivers and employees must complete it', 'Four hours of suicide prevention training before her first day of work, and none after that', 'One hour of training annually, but only if she transports children or is ever alone with a child'], correct: 1, explanation: 'Under the model policy in §748.125(c)(1), all caregivers and employees must complete at least one hour of annual suicide prevention training with a curriculum covering risk factors, protective factors, warning signs, safety planning, and screening. An alternative policy under §748.124(a)(2)(C) must also require annual training for all caregivers and employees.' },
      { id: 'e8q22', domain: 'Service Planning & Treatment', question: 'You are the GRO administrator. An admission assessment lacks the child\'s school history. Yesterday afternoon you called the caseworker three times with no answer and documented three attempts. Does that satisfy "reasonable efforts" under §748.1221?', options: ['Yes; three documented attempts always satisfy the reasonable-efforts requirement, regardless of how close together in time they were made', 'Yes, if you also notify Licensing of the missing information within 24 hours of the third attempt', 'No; the operation may not keep the child in care at all until the full school history has been obtained from the caseworker', 'No; attempts should be reasonably spaced, such as once a week for three weeks, and you must document why the information is unavailable'], correct: 3, explanation: '§748.1221 requires reasonable efforts to obtain required admission assessment information and documentation in the assessment of why information is unavailable. The technical assistance explains that Licensing expects at least three attempts and that calling three times in one day is not three separate reasonable efforts, while calling once a week for three weeks would be.' },
      { id: 'e8q23', domain: 'Service Planning & Treatment', question: 'You are the GRO administrator. A child with a severe food allergy is admitted late on a Friday evening. Which action meets §748.1213?', options: ['Share the allergy at the child\'s first service planning meeting, since the service plan is where special dietary needs are recorded and shared', 'Give the information to the day shift on Monday, when the cottage\'s regular caregivers return to work', 'By the day of admission, inform the responsible caregivers of the child\'s immediate needs and the allergy, and document that you shared it', 'Record the allergy in the child\'s file and let the caregivers read it when they have time to review the file'], correct: 2, explanation: '§748.1213(a) requires that by the day you admit a child, caregivers responsible for the child\'s care be given information about immediate needs, and §748.1213(b) requires informing appropriate caregivers of special needs, such as medical or dietary needs, and documenting that you shared the information.' },
      { id: 'e8q24', domain: 'Service Planning & Treatment', question: 'You are the GRO administrator. A child with an emotional disorder is admitted for treatment services. Besides the child\'s immediate treatment and care needs, what must the preliminary service plan identify under §748.1331(b)(4)?', options: ['The child\'s discharge goals and estimated length of stay, so that caregivers know when treatment will be complete', 'A signed safety contract between the child and the treatment director describing how the child\'s safety needs will be maintained at night', 'The child\'s long-range education and employment plan, including post-secondary training and vocational interests', 'Issues or concerns that could escalate the child\'s behavior, such as food, eye contact, or physical touch, to avoid unnecessary EBI'], correct: 3, explanation: 'For a child receiving treatment services, §748.1331(b)(4) requires the preliminary service plan, completed within 72 hours, to identify any issues or concerns that could escalate the child\'s behavior so the use of unnecessary emergency behavior interventions is avoided. Examples include issues with food, eye contact, physical touch, personal property, or certain topics.' },
      { id: 'e8q25', domain: 'Service Planning & Treatment', question: 'You are the GRO administrator. The psychiatrist on a child\'s service planning team cannot attend the scheduled meeting, and you propose a separate meeting for the psychiatrist. Is that allowed under §748.1340?', options: ['Yes, as long as each team member is informed of the discussions and comments made in each meeting', 'No; the psychiatrist and every other member must attend one single meeting for the service plan to be valid and signed', 'Yes, but the psychiatrist\'s input may be given only in writing and must be attached to the plan', 'Yes, but the plan is not valid until a full-team meeting is also held with the parents present'], correct: 0, explanation: '§748.1340 allows the service planning team to meet in one meeting, two or more meetings, or separate meetings, provided each team member is informed of the discussions and comments about the child\'s service plan that were made in each meeting.' },
      { id: 'e8q26', domain: 'Service Planning & Treatment', question: 'You are the GRO administrator. At a child\'s scheduled service plan review, the team finds no progress toward meeting the child\'s identified needs. What must you do under §748.1385(4)?', options: ['Discharge the child within 30 days', 'Document the reasons for the child\'s continued placement', 'Request a court order to continue the placement', 'Complete a new admission assessment before the next review'], correct: 1, explanation: 'When a service plan review shows no progress toward meeting the child\'s identified needs, §748.1385(4) requires you to document the reasons for continued placement. The review must also evaluate progress, identify new needs and strategies, and document participants (§748.1385(1), (2), (10)).' },
      { id: 'e8q27', domain: 'Service Planning & Treatment', question: 'You are the GRO administrator. A man claiming to be a child\'s uncle arrives to take the child for the weekend. He is not on the parent\'s approved list, and the caregiver does not know him. What is the best course of action?', options: ['Release the child to him if he shows valid photo identification, signs the child out on the visitor log, and promises a time of return', 'Release the child after the caregiver telephones the administrator, who verbally approves the visit based on the man\'s description of his relationship', 'Do not release the child unless he is the parent, a designee of the parent, law enforcement, or a person authorized by law, and follow your identity policy', 'Release the child and record the man\'s name and identification in the log once the weekend visit is over'], correct: 2, explanation: 'Under §748.1481(a), except in an emergency, you may release a child only to the parent, a person designated by the parent, law enforcement authorities, or a person authorized by law to take possession of the child. §748.1481(b) requires employees to follow your policies for releasing a child, verifying the identity of unfamiliar persons, recording their identity, and retaining that information until the child returns.' },
      { id: 'e8q28', domain: 'Service Planning & Treatment', question: 'You are the GRO administrator. You want to place a child who receives only child-care services in a cottage with children receiving treatment services. What must happen first under §748.1201(a)?', options: ['A professional level service provider evaluates the living quarters for the child, confirming no conflict of care and that all needs can be met', 'The treatment director verbally approves the move after reviewing the child\'s admission assessment, the cottage\'s current census, and the cottage\'s staffing pattern', 'The parent of each child already living in the cottage consents in writing to the new child\'s placement', 'Licensing approves an amendment to your permit that adds child-care services to the cottage\'s approved services'], correct: 0, explanation: '§748.1201(a) lets children receiving different types of service share living quarters if a professional level service provider completes an evaluation for each child placed there and ensures there is no conflict of care, no adverse impact on the other children, an appropriate number of children, adequate supervision, and that you can meet everyone\'s needs.' },
      { id: 'e8q29', domain: 'Child Rights & Discipline', question: 'You are the GRO administrator. Your operation is not a residential treatment center and does not provide emergency care services. You want caregivers to search every child\'s backpack when the children return from school each day. What is the best course of action?', options: ['Adopt the policy, because routine searches are allowed at any operation as long as they are justified in policy and applied uniformly to every child', 'Adopt the policy, as long as no search ever involves the removal of clothing other than outer clothing', 'Adopt the policy, as long as each child\'s parent consents to routine searches in writing at admission', 'Do not adopt routine searches; a search of a child or possessions requires reasonable suspicion, such as a prohibited item, suicidal threats, or theft'], correct: 3, explanation: '§748.1113(b) allows searches of a child, possessions, or room only on reasonable suspicion of a prohibited or dangerous item, suicidal or violent threats, or theft. Under §748.1113(c), only residential treatment centers and emergency care services programs may conduct routine searches, and then only if justified in policy, conducted uniformly, and without removing clothing other than outer clothing.' },
      { id: 'e8q30', domain: 'Child Rights & Discipline', question: 'You are the GRO administrator. You suspect a child hid pills in her mouth, and a caregiver proposes a thorough body cavity search. What does §748.1115 permit?', options: ['A same-gender caregiver may conduct it if a second caregiver witnesses it', 'A caregiver may conduct it with the administrator\'s written approval', 'A caregiver may not conduct a body cavity search except of the child\'s mouth', 'A caregiver may conduct it while a health-care professional advises by phone'], correct: 2, explanation: '§748.1115 provides that, with the exception of a child\'s mouth, a caregiver may not conduct a body cavity search of a child in care. This standard is weighted High. Any search must also be documented under §748.1117.' },
      { id: 'e8q31', domain: 'Child Rights & Discipline', question: 'You are the GRO administrator. You discover a caregiver has been opening and reading a 14-year-old\'s letters from friends, with no determination by anyone. What should you do?', options: ['Stop it; mail may be opened only on a decision of the team, treatment director, professional level service provider, or parent, or to help the child read', 'Allow it, because caregivers may screen a child\'s mail for prohibited items or harmful contacts as a routine part of supervising the child and keeping the home safe', 'Allow it if the child is told in advance that caregivers will read the mail', 'Allow it if copies of the letters are placed in the child\'s file for the service planning team to review'], correct: 0, explanation: '§748.1111(a)(1) prohibits opening or reading a child\'s incoming or outgoing mail, including electronic mail, except as determined by the service planning team, treatment director, professional level service provider, or parent, or when necessary to assist the child with reading or writing. Any restriction must be documented, explained to the child and parent, and re-evaluated monthly if it continues beyond 30 days (§748.1111(b)-(d)).' },
      { id: 'e8q32', domain: 'Child Rights & Discipline', question: 'You are the GRO administrator. A child\'s father, whose parental rights have not been terminated, has a court-ordered visitation schedule. A caregiver wants to cancel the next two visits because of the child\'s behavior this week. What is the best course of action?', options: ['Cancel the visits if the caregiver documents the behavior in the child\'s record, tells the father the reason, and offers make-up visits later', 'Do not cancel them as punishment; denying family visits as discipline is prohibited, and contact must follow your policies and the court order', 'Cancel the visits if the child\'s counselor agrees that missing them would help the child learn from the behavior and the child is told why', 'Cancel the visits for up to 14 days without approval, because restrictions that short need no review by anyone'], correct: 1, explanation: '§748.1107(a) requires you to allow contact with a parent whose rights have not been terminated according to your policies and any court order or visitation agreement. Denial of mail or visits with family as discipline or punishment is prohibited (§748.2307(2); §748.1101(b)(4)(A)(iv)).' },
      { id: 'e8q33', domain: 'Child Rights & Discipline', question: 'You are the GRO administrator. A caregiver, frustrated by a child\'s cursing, places a drop of hot sauce on the child\'s tongue. How is this classified?', options: ['Prohibited; putting anything in or on a child\'s mouth as discipline is never allowed', 'Acceptable, if the child is warned first and the amount used is small enough to be harmless', 'Acceptable, if the treatment director approves the technique in the child\'s service plan', 'Prohibited only if the child is under 10 years old or has a documented food allergy'], correct: 0, explanation: '§748.2307(7) prohibits putting anything in or on a child\'s mouth as discipline or punishment, and its technical assistance gives soap, tape, hot peppers, and hot sauce as examples. The standard is weighted High.' },
      { id: 'e8q34', domain: 'Child Rights & Discipline', question: 'You are the GRO administrator. A trusted 17-year-old resident has been assigned to run the evening chores and impose consequences on younger residents. What do you do?', options: ['Allow it with written approval from the child\'s service planning team and a caregiver\'s signature on each consequence', 'End the arrangement; a child in care must not discipline another person in care or be used as a caregiver', 'Allow it as long as a caregiver is on the premises and available to step in if there is a problem', 'Allow it if the consequences are verbal only and the 17-year-old documents each one in a daily log'], correct: 1, explanation: '§748.2311 states that a person in care must not discipline or punish another person in care. In addition, §748.535(3)(G) makes the administrator responsible for ensuring a child in care is not assigned, utilized, or allowed to act as a caregiver.' },
      { id: 'e8q35', domain: 'Child Rights & Discipline', question: 'You are the GRO administrator. A 9-year-old begins punching a peer, and a caregiver quickly holds him face-down on the floor for 40 seconds as a short personal restraint. What is the problem?', options: ['Nothing is wrong; short personal restraints may last up to 10 minutes if the child is supervised', 'The restraint exceeded the 30-second limit that applies to every short personal restraint', 'A prone or supine position may not be used as a short personal restraint', 'It was acceptable because a written order for personal restraint was on file in the child\'s record'], correct: 2, explanation: '§748.2461(b)(1) prohibits a prone or supine restraint as a short personal restraint. Prone and supine holds are allowed only under §748.2605(b) as a transitional hold of no more than one minute, as a last resort, with a qualified observer when the operation\'s capacity is more than 16 children. A short personal restraint also lasts no longer than one minute and does not require orders.' },
      { id: 'e8q36', domain: 'Child Rights & Discipline', question: 'You are the GRO administrator. A child in an approved seclusion falls asleep. What must the caregiver do under §748.2553?', options: ['Let him sleep and check on him every 15 minutes until the maximum time for the seclusion ends', 'Leave the door closed until the maximum time for seclusion ends, then open it and evaluate his overall well-being', 'Unlock the door, continuously observe the child until he awakens, and evaluate his overall well-being', 'Move him to his bedroom and discontinue observation, since a sleeping child is no longer a danger'], correct: 2, explanation: 'Under §748.2553(4)(E), if a child falls asleep in seclusion, the caregiver must unlock the door, continuously observe the child until he awakens, and evaluate his overall well-being. Seclusion also requires continuous observation by a caregiver, not by video camera (§748.2651(a)).' },
      { id: 'e8q37', domain: 'Health, Safety & Emergency', question: 'You are the GRO administrator. A child falls from play equipment and may have a broken arm. The caregiver wants to call you for permission before taking the child to the emergency room. What do you tell her?', options: ['Get the administrator\'s approval first so the decision is documented, then call the parent and arrange for a vehicle to take the child to the hospital', 'Wait for the parent\'s consent before going to the emergency room, unless the child loses consciousness', 'Apply first aid and wait an hour to see whether the swelling worsens before deciding on any treatment', 'Immediately have the child treated, call emergency services, or go to the nearest emergency room once other children are supervised; no approval is needed'], correct: 3, explanation: '§748.1553 requires a caregiver, for an injury or illness needing immediate treatment by a health-care professional, to immediately have the child treated, contact emergency services, or take the child to the nearest emergency room after ensuring supervision of other children, and the caregiver must not be required to seek approval. It is weighted High.' },
      { id: 'e8q38', domain: 'Health, Safety & Emergency', question: 'You are the GRO administrator. A child in foster care arrives without any immunization records. May you admit the child?', options: ['Yes, temporarily for 30 days, and you should immediately refer the child to a health-care professional for the required immunizations', 'No; every required immunization must be completed before admission in every case, including for children who are in foster care or homeless', 'Yes, for 90 days while the records are located, and refer the child to a health-care professional within 30 days', 'Yes, indefinitely, if the caseworker promises to send the records and the child has no symptoms of illness'], correct: 0, explanation: '§748.1539(c)(2) provides that a child who is homeless or in foster care shall be admitted temporarily for 30 days if acceptable evidence of immunization is not available, and that you should immediately refer the child to an appropriate health-care professional to obtain the required immunizations.' },
      { id: 'e8q39', domain: 'Health, Safety & Emergency', question: 'You are the GRO administrator. A child is diagnosed with a communicable disease reportable to the Department of State Health Services. When may the child resume routine activities?', options: ['When the child has been without a fever for 24 hours and the caregivers see no remaining symptoms, as is the practice for common childhood illnesses', 'When the child\'s parent gives verbal permission and the caregiver documents the call in the child\'s record', 'When a health-care professional authorizes it in writing, with a statement that the child will not pose a serious threat to the health of others', 'When the administrator determines that the child feels better and is able to take part in normal activities'], correct: 2, explanation: 'Under §748.1581(c), if a health-care professional diagnoses a child with a communicable disease reportable to DSHS, a health-care professional must authorize the child\'s participation in routine activities. The authorization must be in the child\'s record and include a written statement that the child will not pose a serious threat to others and any specific precautions. You must also notify DSHS (§748.1581(a)).' },
      { id: 'e8q40', domain: 'Health, Safety & Emergency', question: 'You are the GRO administrator. A child recently started a new prescription, and caregivers note mild drowsiness that is not serious. What must you do under §748.2233?', options: ['Document the observed side effects and report them to the prescribing health-care professional within 72 hours', 'Report the side effect immediately to the prescriber and the child\'s parent, because every side effect is treated as serious', 'Document nothing unless the drowsiness lasts for 7 days, then notify the prescriber at the next appointment', 'Stop the medication until Licensing has been notified and the parent has given new written consent'], correct: 0, explanation: '§748.2233(b) requires you to document observed and reported side effects, to immediately report any serious side effects to the prescribing health-care professional and the child\'s parent, and to report any other side effect to the prescribing health-care professional within 72 hours.' },
      { id: 'e8q41', domain: 'Health, Safety & Emergency', question: 'You are the GRO administrator. During a walkthrough you notice that the second exit route on a building\'s evacuation diagram passes through the kitchen. What is the best course of action?', options: ['Keep the route; kitchens are acceptable exits as long as the kitchen doors are never locked and the floor stays clear of obstructions', 'Keep the route if the kitchen is staffed by an employee during every drill and the children practice using it', 'Keep the route if the diagram labels the kitchen as a primary exit and the cook has been trained on evacuation', 'Change the route unless the state or local fire inspector approves it in a signed, dated written approval kept at the operation'], correct: 3, explanation: 'Under §748.3233(b)(4), the diagram must show at least two exit routes in distant parts of the building that are not blocked and are not through a kitchen or other hazardous area, unless specifically approved in writing by the state or local fire inspector. The written approval must be signed and dated and maintained at the operation for Licensing\'s review (§748.3233(b)(4)(C)).' },
      { id: 'e8q42', domain: 'Health, Safety & Emergency', question: 'You are the GRO administrator. An archery club on your campus invites residents to join, and your weapons policy permits archery for some children. A 13-year-old who receives treatment services for an emotional disorder wants to participate. What is correct?', options: ['He may participate with direct supervision from an adult who is knowledgeable about archery, just as for any other child in care', 'He may not participate, because a child receiving treatment services may not use weapons, firearms, explosive materials, or projectiles', 'He may participate if the treatment director approves the activity in his service plan and the parent consents in writing', 'He may participate after completing a safety class and demonstrating safe handling to the archery instructor'], correct: 1, explanation: '§748.3931(a)(2) states that a child receiving treatment services or emergency care services is not permitted to use weapons, firearms, explosive materials, or projectiles (such as darts or arrows). Direct supervision by a knowledgeable adult (§748.3931(a)(5)) applies to children who are allowed to use them, such as those receiving only child-care services.' },
      { id: 'e8q43', domain: 'Health, Safety & Emergency', question: 'You are the GRO administrator. A child is admitted at 2:00 a.m., and no bedroom is ready. May you place her on a cot in the living room?', options: ['Yes, for the first night only, if she has comfortable sleeping arrangements and her supervision is not compromised', 'Yes, for up to three nights as long as a caregiver stays awake in the room and the child agrees', 'No; a living room may never be used for sleeping, even for a child who is admitted during sleeping hours on a night when no bedroom is open', 'Yes, as long as the living room has an outside window and the cot is away from the exit'], correct: 0, explanation: '§748.3359(1) prohibits using rooms commonly used for other purposes, such as living rooms, as bedrooms, with an exception for a child who is admitted to your operation during sleeping hours (for the first night only), provided the child has comfortable sleeping arrangements and supervision is not compromised.' },
      { id: 'e8q44', domain: 'Health, Safety & Emergency', question: 'You are the GRO administrator. A physician phones in a dosage change for a child\'s prescription, and a caregiver takes the order. What must you ensure under §748.2005?', options: ['The caregiver documents the order with the physician\'s name and the date and time of the call, and the physician signs written orders within 72 hours', 'The order is followed only after the physician faxes a written copy to the operation within 24 hours, and Licensing is notified of the change', 'The caregiver documents the order, and the physician signs it at the child\'s next scheduled appointment', 'Verbal orders are never accepted for prescription medication, so the caregiver must wait for a written order from the physician before any change is made'], correct: 0, explanation: 'Under §748.2005, once written consent has been obtained under §748.2001, a licensed health-care professional may give verbal orders, but must write and sign the orders within 72 hours. The verbal order must be documented in the child\'s record, including the professional\'s name and the date and time of the call.' },
      { id: 'e8q45', domain: 'Daily Care & Program Operations', question: 'You are the GRO administrator on a ranch outing. A 15-year-old and a 16-year-old ask to ride all-terrain vehicles. The ranch has a three-wheel ATV and a four-wheel ATV. What is permitted?', options: ['Both may ride the four-wheel ATV with adult supervision, because it is permitted for children who are 15 or older', 'Both may ride either ATV, as long as they wear helmets and receive instruction from the ranch staff', 'Only the 16-year-old may ride, on either ATV, as long as an adult riding beside him can see him at all times', 'Only the 16-year-old may ride, and only the four-wheel ATV; no child in care may ride or operate a three-wheel ATV'], correct: 3, explanation: '§748.3719 provides that a child in care may not ride on or operate a three-wheel all-terrain vehicle, and that only a child 16 years or older may ride on or operate a four-wheel all-terrain vehicle. ATVs are higher risk recreational activities under §748.3705.' },
      { id: 'e8q46', domain: 'Daily Care & Program Operations', question: 'You are the GRO administrator. You take nine children, ages 9 to 15, to a lake for a swimming activity sponsored by the operation. What must you have under §748.3751(b) and §748.3765(b)?', options: ['Only one adult who can swim or is trained in water rescue, because the outing is away from the operation and the group is small', 'A lifeguard only if some child cannot swim, plus a safety throw bag only if the water is deeper than 4 feet', 'A certified lifeguard on duty but no life-saving equipment, since the lifeguard is the required rescue resource', 'A certified lifeguard on duty and life-saving equipment such as a 50-foot throw rope, because more than six children are participating'], correct: 3, explanation: 'For swimming activities away from the operation involving water two feet deep or more, an adult able to swim or trained in water rescue is enough for six or fewer children, but if more than six children participate, a certified lifeguard must also be on duty (§748.3751(b)). §748.3765(b)(3) also requires life-saving equipment, such as a safety throw bag with a brightly colored 50-foot buoyant rope, when more than six children participate.' },
      { id: 'e8q47', domain: 'Daily Care & Program Operations', question: 'You are the GRO administrator planning a seven-hour day hike on trails unfamiliar to the adults. What documentation must you have under §748.3845?', options: ['Only an emergency contact list for the adults, because a day hike is not an overnight excursion', 'A pre-departure itinerary with departure and return times, destination, and travel route, with a copy kept on file at the operation', 'A written itinerary only if the hike is overnight, since shorter hikes need only the adults\' verbal agreement', 'A hike plan filed with Licensing at least 15 days beforehand, with a signed permission slip from each child\'s parent'], correct: 1, explanation: '§748.3845(a) requires an itinerary prepared before departure for hiking or camping excursions lasting over five hours, including the time of departure and anticipated return, destination, and travel route. Overnight excursions need additional itinerary details (§748.3845(b)), and §748.3847(a) requires a copy of the itinerary to be kept on file at the operation.' },
      { id: 'e8q48', domain: 'Daily Care & Program Operations', question: 'You are the GRO administrator at a campus that is not a cottage home. At an outdoor cookout in 95-degree weather, leftover chicken sits out. Within what time must perishable food be refrigerated under §748.3441(q)?', options: ['Within two hours after use', 'Within one hour after use', 'Within 30 minutes after use', 'Within four hours after use'], correct: 1, explanation: '§748.3441(q) requires perishable food to be refrigerated within one hour after use when the temperature is above 90 degrees Fahrenheit, and otherwise within two hours. Subsection (t) exempts cottage homes from this rule.' },
      { id: 'e8q49', domain: 'Daily Care & Program Operations', question: 'You are the GRO administrator. A child with an individual education plan (IEP) is enrolled at a school that has not been implementing it. What is your responsibility under §748.1301(a)?', options: ['Ensure the child attends a program that implements the IEP, and advocate that the child receives the services to which he is entitled by law', 'Withdraw the child from the school and provide the instruction at the operation yourself with your own teachers', 'Notify Licensing of the school\'s failure and wait for Licensing to contact the school about the IEP', 'Leave the matter to the child\'s parent, because the school is outside your control and the IEP is a school document'], correct: 0, explanation: '§748.1301(a) requires you to arrange an appropriate education for each child, including ensuring the child attends an educational facility or program that implements a special education student\'s IEP (§748.1301(a)(3)) and advocating that a school-age child receives the educational and related services to which he is entitled under federal and state law (§748.1301(a)(4)). Under §748.1303(8) you must also know what is in the IEP and support the school\'s efforts to implement it.' },
      { id: 'e8q50', domain: 'Daily Care & Program Operations', question: 'You are the GRO administrator. You admit a child who receives treatment services for an emotional disorder. What does §748.3701 require for the child\'s recreation?', options: ['The same recreation schedule as the other residents, since daily indoor and outdoor recreation is already required for every child', 'A recreation plan approved in writing by the child\'s parent and reviewed by the administrator each month', 'Indoor recreation only, to limit the child\'s risk of injury and the chance of a runaway', 'An individualized recreation plan designed by the service planning team or qualified professionals, implemented, and revised as needed'], correct: 3, explanation: '§748.3701(a) requires daily indoor and outdoor recreation for all children, and §748.3701(e)(2) adds that each child receiving treatment services must have an individualized recreation plan designed by the service planning team or qualified professionals, implemented, and revised as needed, along with opportunities for community activities.' },
    ],
  },
];
